module art_reproduction (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] grid [0:7][0:7],\n    output reg done,\n    output reg result\n);\n\n    // State declarations\n    localparam [2:0] S_IDLE   = 3'd0;\n    localparam [2:0] S_SCAN   = 3'd1;\n    localparam [2:0] S_REMOVE = 3'd2;\n    localparam [2:0] S_CHECK  = 3'd3;\n    localparam [2:0] S_DONE   = 3'd4;\n\n    // Color definitions\n    localparam [1:0] COLOR_W = 2'b00;\n    \n    // Internal registers\n    reg [1:0] board [0:7][0:7];\n    reg [5:0] iter_count;\n    reg [2:0] scan_x;\n    reg [2:0] scan_y;\n    reg found_block;\n    reg all_white;\n    reg [2:0] state;\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 1'b0;\n            state <= S_IDLE;\n            iter_count <= 6'd0;\n            scan_x <= 3'd0;\n            scan_y <= 3'd0;\n            found_block <= 1'b0;\n            all_white <= 1'b1;\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    board[i][j] <= COLOR_W;\n                end\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Copy input grid\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                board[i][j] <= grid[i][j];\n                            end\n                        end\n                        iter_count <= 6'd0;\n                        scan_x <= 3'd0;\n                        scan_y <= 3'd0;\n                        state <= S_SCAN;\n                    end\n                end\n\n                S_SCAN: begin\n                    found_block <= 1'b0;\n                    if (\n                        (scan_x <= 3'd5) && \n                        (scan_y <= 3'd5) && \n                        (board[scan_x][scan_y] != COLOR_W) &&\n                        (board[scan_x][scan_y] == board[scan_x][scan_y+3'd1]) && \n                        (board[scan_x][scan_y] == board[scan_x][scan_y+3'd2]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd1][scan_y]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd1][scan_y+3'd1]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd1][scan_y+3'd2]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd2][scan_y]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd2][scan_y+3'd1]) && \n                        (board[scan_x][scan_y] == board[scan_x+3'd2][scan_y+3'd2])\n                    ) begin\n                        found_block <= 1'b1;\n                        state <= S_REMOVE;\n                    end else if (scan_x == 3'd5) begin\n                        scan_x <= 3'd0;\n                        if (scan_y == 3'd5) begin\n                            state <= S_CHECK;\n                        end else begin\n                            scan_y <= scan_y + 3'd1;\n                        end\n                    end else begin\n                        scan_x <= scan_x + 3'd1;\n                    end\n                end\n\n                S_REMOVE: begin\n                    // Set 3x3 block to white\n                    board[scan_x][scan_y] <= COLOR_W;\n                    board[scan_x][scan_y+3'd1] <= COLOR_W;\n                    board[scan_x][scan_y+3'd2] <= COLOR_W;\n                    board[scan_x+3'd1][scan_y] <= COLOR_W;\n                    board[scan_x+3'd1][scan_y+3'd1] <= COLOR_W;\n                    board[scan_x+3'd1][scan_y+3'd2] <= COLOR_W;\n                    board[scan_x+3'd2][scan_y] <= COLOR_W;\n                    board[scan_x+3'd2][scan_y+3'd1] <= COLOR_W;\n                    board[scan_x+3'd2][scan_y+3'd2] <= COLOR_W;\n                    \n                    iter_count <= iter_count + 6'd1;\n                    state <= S_SCAN;\n                end\n\n                S_CHECK: begin\n                    all_white <= 1'b1;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (board[i][j] != COLOR_W) begin\n                                all_white <= 1'b0;\n                            end\n                        end\n                    end\n\n                    if (all_white) begin\n                        result <= 1'b1;\n                        state <= S_DONE;\n                    end else if (iter_count >= 6'd64) begin\n                        result <= 1'b0;\n                        state <= S_DONE;\n                    end else begin\n                        scan_x <= 3'd0;\n                        scan_y <= 3'd0;\n                        state <= S_SCAN;\n                    end\n                end\n\n                S_DONE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= S_IDLE;\n                    end\n                end\n\n                default: begin\n                    state <= S_IDLE;\n                end\n            endcase\n        end\n    end\nendmodule